<script setup lang="ts">
import { RefreshCw } from "lucide-vue-next";import type { ImportJob } from "~/types/api";import { formatDate,formatNumber } from "~/utils/format";
const api=useApi();const jobs=ref<ImportJob[]>([]),loading=ref(true),message=ref(""),errorsOpen=ref(false),errors=ref<Array<Record<string,unknown>>>([]),selected=ref<ImportJob|null>(null);
async function load(){loading.value=true;try{jobs.value=await api.get<ImportJob[]>("/importacoes");}catch(cause){message.value=cause instanceof Error?cause.message:"Erro ao carregar importações.";}finally{loading.value=false;}}
async function showErrors(job:ImportJob){selected.value=job;try{errors.value=(await api.get<{items:Array<Record<string,unknown>>}>(`/importacoes/${job.id}/erros`)).items;errorsOpen.value=true;}catch(cause){message.value=cause instanceof Error?cause.message:"Erro ao carregar erros.";}}
onMounted(load);
</script>
<template><section class="surface"><header class="surface-header"><div><h2>Histórico de importações</h2><p>Jobs, lotes e registros rejeitados.</p></div><button class="btn btn-icon" @click="load"><RefreshCw :size="16"/></button></header><div class="surface-body stack"><p v-if="message" class="notice error">{{message}}</p><div v-if="loading" class="loading-state"><div class="spinner"/></div><div v-else class="table-wrap"><table class="data-table"><thead><tr><th>Início</th><th>Módulo</th><th>Arquivo</th><th>Status</th><th class="numeric">Encontrados</th><th class="numeric">Inseridos</th><th class="numeric">Atualizados</th><th class="numeric">Ignorados</th><th class="numeric">Rejeitados</th></tr></thead><tbody><tr v-for="job in jobs" :key="job.id" @click="job.totalRejected&&showErrors(job)"><td>{{formatDate(job.startedAt,true)}}</td><td><span class="badge info">{{job.module}}</span></td><td>{{job.fileName}}</td><td>{{job.status}}</td><td class="numeric">{{formatNumber(job.totalFound)}}</td><td class="numeric">{{formatNumber(job.totalInserted)}}</td><td class="numeric">{{formatNumber(job.totalUpdated)}}</td><td class="numeric">{{formatNumber(job.totalIgnored)}}</td><td class="numeric"><button v-if="job.totalRejected" class="btn danger small" @click.stop="showErrors(job)">{{job.totalRejected}}</button><span v-else>0</span></td></tr></tbody></table></div></div><AppModal :open="errorsOpen" :title="`Erros — ${selected?.fileName||''}`" @close="errorsOpen=false"><div class="table-wrap"><table class="data-table"><thead><tr><th>Lote</th><th>Linha</th><th>Campo</th><th>Mensagem</th></tr></thead><tbody><tr v-for="(error,index) in errors" :key="index"><td>{{error.batchNumber||'—'}}</td><td>{{error.rowNumber||'—'}}</td><td>{{error.field||'—'}}</td><td>{{error.message}}</td></tr></tbody></table></div></AppModal></section></template>
